 "content": "def transform(grid):
    # Each marker is an endpoint of a diagonal stroke of its own color. The demos
    # show strokes continuing to the grid edge, not finite connections between pairs.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    for color in (1, 6):
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Diagonal slope is the common slope between same-color points when present;
        # isolated-color patterns in demos continue along their marked diagonal.
        slope = None
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i+1:]:
                dr, dc = r2-r1, c2-c1
                if dr and abs(dr) == abs(dc):
                    slope = (1 if dr*dc > 0 else -1)
                    break
            if slope is not None:
                break
        if slope is None:
            continue
        for r, c in points:
            # extend along both directions on this diagonal, preserving existing markers
            for sign in (-1, 1):
                rr, cc = r+sign, c+sign*slope
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == bg:
                        out[rr][cc] = color
                    rr += sign
                    cc += sign*slope
    return out
",
 "cross_profile": false
}

